27:  * Blink timing.
28:  *
29:  * A real blink is ~210ms and irregular. Both matter: a metronomic blink is one
30:  * of the strongest "this is a puppet" signals there is, which is why the next
31:  * one is scheduled from a random interval rather than a fixed one.
32:  */
33: const BLINK_CLOSE = 60;
34: const BLINK_HOLD = 40;
35: const BLINK_OPEN = 110;
36: const BLINK_TOTAL = BLINK_CLOSE + BLINK_HOLD + BLINK_OPEN;
37: 
38: export function useBlinkTimer() {
39:   const state = useRef({ next: 1200, elapsed: 0, phase: 0 });
40: 
41:   /** Advances the blink clock and returns 0→1 eyelid closure. */
42:   return (deltaMs: number): number => {
43:     const s = state.current;
44:     s.elapsed += deltaMs;
45: 
46:     if (s.phase === 0) {
47:       if (s.elapsed < s.next) return 0;
48:       s.phase = 1;
49:       s.elapsed = 0;
50:     }
51: 
52:     const t = s.elapsed;
53:     if (t >= BLINK_TOTAL) {
54:       s.phase = 0;
55:       s.elapsed = 0;
56:       // 2.4–6s, with a 15% chance of a quick double-blink.
57:       s.next = Math.random() < 0.15 ? 180 : 2400 + Math.random() * 3600;
58:       return 0;
59:     }
60: 
61:     if (t < BLINK_CLOSE) return t / BLINK_CLOSE;
62:     if (t < BLINK_CLOSE + BLINK_HOLD) return 1;
63:     return 1 - (t - BLINK_CLOSE - BLINK_HOLD) / BLINK_OPEN;
64:   };
65: }
