81:     if (s.holding > 0) {
82:       s.holding -= deltaMs;
83:       if (s.holding <= 0) {
84:         s.offsetX = 0;
85:         s.offsetY = 0;
86:       }
87:     } else if (s.elapsed >= s.next) {
88:       s.elapsed = 0;
89:       s.next = 1400 + Math.random() * 1800;
90:       s.offsetX = (Math.random() - 0.5) * 0.24;
91:       s.offsetY = (Math.random() - 0.5) * 0.16;
