1: "use client";
2: 
3: import {
4:   Suspense,
5:   useEffect,
6:   useState,
7:   useSyncExternalStore,
8:   type ReactNode,
9: } from "react";
10: import { Canvas } from "@react-three/fiber";
11: import { Environment, Lightformer } from "@react-three/drei";
12: import * as THREE from "three";
13: 
14: import { HEX } from "@/lib/three-palette";
15: import { dprRange, qualityTier, type QualityTier } from "@/lib/webgl";
16: 
17: /**
18:  * The house canvas.
19:  *
20:  * Every showcase scene mounts through this so they share one look: the same
21:  * tone mapping, the same studio environment, the same grade. Scenes that each
22:  * invent their own lighting are the main reason a site full of 3D ends up
23:  * looking like a site full of demos.
24:  *
25:  * Two decisions worth stating, because both look like omissions:
26:  *
27:  * **No `<Environment preset="...">`.** drei's presets fetch an HDRI from its
28:  * CDN at runtime — an external dependency on the critical path of the thing the
29:  * page exists for, and a warm outdoor bounce that fights the gallery look. The
30:  * environment here is built from `<Lightformer>` rectangles instead: fully
31:  * procedural, zero bytes, baked once (`frames={1}`), and controllable in a way
32:  * a photograph is not. On glazing and polished metal — which is most of what
33:  * these scenes are made of — the shape of the reflected light *is* the render.
34:  *
35:  * **No shadows by default.** They are opt-in per scene, because a shadow camera
36:  * fitted to the wrong bounds costs a lot and produces mush.
37:  */
38: 
39: /** Hardware capability does not change mid-session, so there is nothing to
40:     subscribe to. Declared at module scope so the reference stays stable. */
41: const noopSubscribe = () => () => {};
42: 
43: /** Lightformer takes CSS colour strings, the palette stores hex numbers. */
44: const hex = (value: number) => `#${value.toString(16).padStart(6, "0")}`;
45: 
46: export type SceneFrameProps = {
47:   /** A function form receives the resolved quality tier, which scenes need for
48:       instance counts and shadow decisions. */
49:   children: ReactNode | ((tier: QualityTier) => ReactNode);
50:   /** Initial camera. Scenes that animate the camera take over from here. */
51:   camera?: { position: [number, number, number]; fov?: number };
52:   /** Transparent canvas, for compositing over a CSS background. */
53:   transparent?: boolean;
54:   /** Distance fog, matched to the page ground so the scene fades into it. */
55:   fog?: { near: number; far: number } | false;
56:   className?: string;
57:   /** Extra effects beyond the house grade. */
58:   effects?: (tier: QualityTier) => ReactNode;
59: };
60: 
61: export function SceneFrame({
62:   children,
63:   camera = { position: [0, 2, 8], fov: 38 },
64:   transparent = false,
65:   fog = { near: 18, far: 60 },
66:   className,
67:   effects,
68: }: SceneFrameProps) {
69:   /* Resolved on the client only — reading `navigator` during render would give
70:      the server a different answer than the browser. The subscribe function is a
71:      no-op because hardware does not change mid-session; `getSnapshot` returns a
72:      string, so React's identity check compares by value and cannot loop. */
73:   const tier = useSyncExternalStore(
74:     noopSubscribe,
75:     qualityTier,
76:     () => null as QualityTier | null,
77:   );
78: 
79:   if (tier === null) return null;
80: 
81:   return (
82:     <Canvas
83:       className={className}
84:       dpr={dprRange(tier)}
85:       camera={{ position: camera.position, fov: camera.fov ?? 38, near: 0.1, far: 200 }}
86:       gl={{
87:         antialias: tier !== "low",
88:         alpha: transparent,
89:         powerPreference: "high-performance",
90:       }}
91:       onCreated={({ gl }) => {
92:         // ACES is what stops bright metal and lit windows clipping to flat
93:         // white; the slight exposure lift keeps the near-black ground from
94:         // crushing everything into it.
95:         gl.toneMapping = THREE.ACESFilmicToneMapping;
96:         // ACES rolls highlights off hard, so the exposure has to be pushed
97:         // past 1 for a dark set to read as lit rather than merely underexposed.
98:         gl.toneMappingExposure = 1.45;
99:       }}
100:     >
101:       {!transparent && <color attach="background" args={[HEX.ground]} />}
102:       {fog && (
103:         /* Aerial perspective. Without it a tower has no sense of scale —
104:            everything reads as a tabletop model. */
105:         <fog attach="fog" args={[HEX.ground, fog.near, fog.far]} />
106:       )}
107: 
108:       <Suspense fallback={null}>
109:         <StudioEnvironment />
110:         {typeof children === "function" ? children(tier) : children}
111:       </Suspense>
112: 
113:       {effects?.(tier)}
114:     </Canvas>
115:   );
116: }
117: 
118: /**
119:  * A procedural studio, built from emissive rectangles.
120:  *
121:  * Three lights doing three jobs: a broad cool sky panel overhead for ambient
122:  * shape, a narrow bright strip camera-right that becomes the highlight running
123:  * down glass and metal edges, and a warm low panel standing in for city glow
124:  * off the ground. `--navy` finally earns its keep as the sky tint — it is
125:  * defined in the design tokens and used nowhere in the DOM.
126:  */
127: function StudioEnvironment() {
128:   return (
129:     <Environment resolution={256} frames={1}>
130:       {/* Sky. Broad, cool and dim — it does the ambient shaping. */}
131:       <Lightformer
132:         intensity={2.4}
133:         color={hex(HEX.navy)}
134:         form="rect"
135:         position={[0, 14, -6]}
136:         scale={[30, 18, 1]}
137:         rotation={[Math.PI / 2, 0, 0]}
138:       />
139:       {/* The money light: a narrow bright strip camera-right. This is what
140:           becomes the highlight running down glass and metal edges, and it is
141:           the single largest contributor to whether the scene looks expensive. */}
142:       <Lightformer
143:         intensity={9}
144:         color="#ffffff"
145:         form="rect"
146:         position={[9, 8, 6]}
147:         scale={[2, 24, 1]}
148:         rotation={[0, -Math.PI / 3.2, 0]}
149:       />
150:       {/* City glow off the ground, warm and low. */}
151:       <Lightformer
152:         intensity={3}
153:         color={hex(HEX.bronze)}
154:         form="rect"
155:         position={[-9, 1, 4]}
156:         scale={[22, 4, 1]}
157:         rotation={[0, Math.PI / 3, 0]}
158:       />
159:     </Environment>
160:   );
161: }
162: 
163: /**
164:  * The house grade.
165:  *
166:  * Bloom on lit windows and gold trim, a vignette to pull the eye in, and a
167:  * little grain so flat dark areas do not band on cheap panels. Deliberately
168:  * excludes two things `CLAUDE.md` §7 suggests: SSR, which is expensive and
169:  * artefacts badly on instanced geometry, and chromatic aberration, which reads
170:  * as a glitch effect rather than as photography on architecture.
171:  *
172:  * Mounted only on the high tier — postprocessing is a full-screen pass per
173:  * effect, and on a warm phone it is the first thing that should go.
174:  */
175: export function HouseGrade({ tier }: { tier: QualityTier }) {
176:   const [effects, setEffects] = useState<ReactNode>(null);
177: 
178:   useEffect(() => {
179:     if (tier !== "high") return;
180:     let cancelled = false;
181: 
182:     void import("@react-three/postprocessing").then(
183:       ({ EffectComposer, Bloom, Vignette, Noise }) => {
184:         if (cancelled) return;
185:         setEffects(
186:           <EffectComposer>
187:             <Bloom luminanceThreshold={0.9} intensity={0.35} mipmapBlur />
188:             <Vignette offset={0.3} darkness={0.6} />
189:             <Noise opacity={0.025} premultiply />
190:           </EffectComposer>,
191:         );
192:       },
193:     );
194: 
195:     return () => {
196:       cancelled = true;
197:     };
198:   }, [tier]);
199: 
200:   return <>{effects}</>;
201: }
