27: const KEY = "kautilya:visitor";
28: 
29: export type VisitorRecord = {
30:   /** Schema version, so a future shape change can be migrated or discarded. */
31:   v: 1;
32:   /** Null when the visitor skipped rather than answered. */
33:   name: string | null;
34:   /** Epoch ms. Presence of a record at all is what suppresses the gate. */
35:   greetedAt: number;
36: };
