38: /* `getSnapshot` must return a referentially stable value or React re-renders
39:    forever, so the parsed record is cached and only replaced on a real write. */
40: let cached: VisitorRecord | null = null;
41: let loaded = false;
42: const subscribers = new Set<() => void>();
43: 
44: function read(): VisitorRecord | null {
45:   if (loaded) return cached;
46:   loaded = true;
47:   try {
48:     const raw = window.localStorage.getItem(KEY);
49:     if (!raw) return (cached = null);
50:     const parsed = JSON.parse(raw) as VisitorRecord;
51:     cached = parsed?.v === 1 ? parsed : null;
52:   } catch {
53:     // Private mode, a full quota, or someone hand-edited the value. A visitor
54:     // who cannot be remembered simply sees the greeting again.
55:     cached = null;
56:   }
57:   return cached;
58: }
59: 
60: function write(record: VisitorRecord | null) {
61:   cached = record;
62:   loaded = true;
63:   try {
