63:     if (isTouch) return;
64: 
65:     const lenis = new Lenis({ lerp: 0.1, wheelMultiplier: 1 });
66:     publish(lenis);
67: 
68:     let frame = 0;
69:     const raf = (time: number) => {
70:       lenis.raf(time);
71:       frame = requestAnimationFrame(raf);
72:     };
