import { FloorPlan, Room, roomDimensions } from "./floor-plans";
import * as THREE from "three";

export type Wall = {
  x: number;
  y: number;
  w: number;
  h: number;
  isExterior: boolean;
};

export type Doorway = {
  x: number;
  y: number;
  vertical: boolean;
  fromRoom: number;
  toRoom: number;
};

export function generateInterior(plan: FloorPlan, carpetAreaSqFt: number) {
  // Derive scale from the living room (or first room) to match printed dimensions.
  const baseRoom = plan.rooms.find((r) => r.kind === "living") || plan.rooms[0];
  const dimStr = roomDimensions(baseRoom, carpetAreaSqFt);
  const [wStr] = dimStr.replace(" m", "").split(" × ");
  const gridToMeters = parseFloat(wStr) / baseRoom.w;

  const grid = Array.from({ length: plan.height }, () => new Int32Array(plan.width).fill(-1));
  plan.rooms.forEach((room, i) => {
    for (let y = room.y; y < room.y + room.h; y++) {
      for (let x = room.x; x < room.x + room.w; x++) {
        grid[y][x] = i;
      }
    }
  });

  const walls: Wall[] = [];
  const doorways: Doorway[] = [];
  const boundaries = new Map<string, { x: number; y: number; vertical: boolean }[]>();

  // Extract horizontal boundaries
  for (let y = 0; y <= plan.height; y++) {
    for (let x = 0; x < plan.width; x++) {
      const top = y > 0 ? grid[y - 1][x] : -1;
      const bottom = y < plan.height ? grid[y][x] : -1;
      if (top !== bottom) {
        if (top !== -1 && bottom !== -1) {
          const key = [top, bottom].sort().join("-");
          let list = boundaries.get(key);
          if (!list) {
            list = [];
            boundaries.set(key, list);
          }
          list.push({ x, y, vertical: false });
        } else {
          walls.push({ x: x + 0.5, y, w: 1, h: 0.1, isExterior: true });
        }
      }
    }
  }

  // Extract vertical boundaries
  for (let x = 0; x <= plan.width; x++) {
    for (let y = 0; y < plan.height; y++) {
      const left = x > 0 ? grid[y][x - 1] : -1;
      const right = x < plan.width ? grid[y][x] : -1;
      if (left !== right) {
        if (left !== -1 && right !== -1) {
          const key = [left, right].sort().join("-");
          let list = boundaries.get(key);
          if (!list) {
            list = [];
            boundaries.set(key, list);
          }
          list.push({ x, y, vertical: true });
        } else {
          walls.push({ x, y: y + 0.5, w: 0.1, h: 1, isExterior: true });
        }
      }
    }
  }

  // Place doorways and internal walls
  for (const [key, segments] of boundaries.entries()) {
    // Sort segments to find the middle one reliably
    segments.sort((a, b) => (a.vertical ? a.y - b.y : a.x - b.x));
    const midIndex = Math.floor(segments.length / 2);
    const door = segments[midIndex];
    const [a, b] = key.split("-").map(Number);
    doorways.push({
      x: door.x + (door.vertical ? 0 : 0.5),
      y: door.y + (door.vertical ? 0.5 : 0),
      vertical: door.vertical,
      fromRoom: a,
      toRoom: b,
    });

    for (let i = 0; i < segments.length; i++) {
      if (i === midIndex) continue; // Leave a gap for the door
      const s = segments[i];
      if (s.vertical) {
        walls.push({ x: s.x, y: s.y + 0.5, w: 0.1, h: 1, isExterior: false });
      } else {
        walls.push({ x: s.x + 0.5, y: s.y, w: 1, h: 0.1, isExterior: false });
      }
    }
  }

  // Create waypoints for the camera tour
  // The origin is at the top-left of the grid.
  // Let's build an adjacency list of rooms
  const adj = Array.from({ length: plan.rooms.length }, () => [] as { to: number; door: Doorway }[]);
  for (const door of doorways) {
    adj[door.fromRoom].push({ to: door.toRoom, door });
    adj[door.toRoom].push({ to: door.fromRoom, door });
  }

  const waypoints: THREE.Vector3[] = [];
  const visited = new Set<number>();

  // Start near the entry. Find the closest room to the entry coordinate.
  let startRoom = 0;
  let minDist = Infinity;
  plan.rooms.forEach((room, i) => {
    const cx = room.x + room.w / 2;
    const cy = room.y + room.h / 2;
    const dist = Math.hypot(cx - plan.entry.x, cy - plan.entry.y);
    if (dist < minDist) {
      minDist = dist;
      startRoom = i;
    }
  });

  const EYE_HEIGHT = 1.6; // 1.6m eye height

  function getCentroid(roomId: number) {
    const room = plan.rooms[roomId];
    return new THREE.Vector3(
      (room.x + room.w / 2) * gridToMeters,
      EYE_HEIGHT,
      (room.y + room.h / 2) * gridToMeters
    );
  }

  function getDoorPt(door: Doorway) {
    return new THREE.Vector3(
      door.x * gridToMeters,
      EYE_HEIGHT,
      door.y * gridToMeters
    );
  }

  // Add an initial point right at the entry
  waypoints.push(new THREE.Vector3(plan.entry.x * gridToMeters, EYE_HEIGHT, plan.entry.y * gridToMeters));

  function dfs(u: number) {
    visited.add(u);
    waypoints.push(getCentroid(u));

    for (const edge of adj[u]) {
      if (!visited.has(edge.to)) {
        waypoints.push(getDoorPt(edge.door));
        dfs(edge.to);
        // Backtrack
        waypoints.push(getDoorPt(edge.door));
        waypoints.push(getCentroid(u));
      }
    }
  }

  dfs(startRoom);

  // Offset the whole scene so it's centered
  const cx = (plan.width / 2) * gridToMeters;
  const cy = (plan.height / 2) * gridToMeters;
  const offset = new THREE.Vector3(-cx, 0, -cy);

  for (const wp of waypoints) {
    wp.add(offset);
  }

  return {
    walls,
    gridToMeters,
    waypoints,
    offsetX: cx,
    offsetZ: cy,
    width: plan.width,
    height: plan.height,
  };
}

"use client";

import { useRef, useMemo } from "react";
import { useFrame } from "@react-three/fiber";
import { useGLTF, Environment } from "@react-three/drei";
import * as THREE from "three";
import { generateInterior } from "@/lib/interior-generator";
import { getFloorPlan } from "@/lib/floor-plans";
import { useScrollProgress } from "@/components/three/use-scroll-progress";
import { SceneFrame } from "@/components/three/scene-frame";

type Props = {
  sectionRef: React.RefObject<HTMLElement | null>;
  bhk: string;
  carpetAreaSqFt: number;
};

// Scratch objects for useFrame
const dummy = new THREE.Object3D();
const vLook = new THREE.Vector3();
const vPos = new THREE.Vector3();
const WALL_HEIGHT = 3.0; // 3 meters tall

export function ApartmentInteriorScene({ sectionRef, bhk, carpetAreaSqFt }: Props) {
  const plan = getFloorPlan(bhk);

  const { walls, gridToMeters, waypoints, offsetX, offsetZ, width, height } = useMemo(
    () => generateInterior(plan, carpetAreaSqFt),
    [plan, carpetAreaSqFt]
  );

  const spline = useMemo(() => new THREE.CatmullRomCurve3(waypoints, false, "catmullrom", 0.5), [waypoints]);
  const scrollProgress = useScrollProgress(sectionRef);

  // Instanced walls
  const wallMesh = useRef<THREE.InstancedMesh>(null);
  useMemo(() => {
    if (!wallMesh.current) return;
    walls.forEach((wall, i) => {
      // Wall position
      const px = wall.x * gridToMeters - offsetX;
      const pz = wall.y * gridToMeters - offsetZ;
      const py = WALL_HEIGHT / 2;

      const sx = wall.w === 1 ? gridToMeters : 0.15; // 15cm thickness
      const sy = WALL_HEIGHT;
      const sz = wall.h === 1 ? gridToMeters : 0.15;

      dummy.position.set(px, py, pz);
      dummy.scale.set(sx, sy, sz);
      dummy.updateMatrix();
      wallMesh.current!.setMatrixAt(i, dummy.matrix);

      const color = wall.isExterior ? new THREE.Color("#444") : new THREE.Color("#666");
      wallMesh.current!.setColorAt(i, color);
    });
    wallMesh.current.instanceMatrix.needsUpdate = true;
    if (wallMesh.current.instanceColor) wallMesh.current.instanceColor.needsUpdate = true;
  }, [walls, gridToMeters, offsetX, offsetZ]);

  useFrame(({ camera }) => {
    const t = scrollProgress.current;
    if (t < 0) return;

    // Evaluate spline at t
    spline.getPointAt(Math.max(0, Math.min(1, t)), vPos);
    camera.position.copy(vPos);

    // Look slightly ahead
    spline.getPointAt(Math.max(0, Math.min(1, t + 0.02)), vLook);
    // No roll ever: keep y the same for look target so the camera stays level
    vLook.y = vPos.y; 

    if (t >= 0.99) {
      // Look straight ahead at the end
      vLook.sub(vPos).normalize().add(vPos);
    }

    camera.lookAt(vLook);
  });

  return (
    <SceneFrame fog={{ near: 5, far: 50 }}>
      {/* Floor */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0]}>
        <planeGeometry args={[width * gridToMeters, height * gridToMeters]} />
        <meshStandardMaterial color="#2d2a26" />
      </mesh>

      {/* Ceiling */}
      <mesh rotation={[Math.PI / 2, 0, 0]} position={[0, WALL_HEIGHT, 0]}>
        <planeGeometry args={[width * gridToMeters, height * gridToMeters]} />
        <meshStandardMaterial color="#ffffff" />
      </mesh>

      {/* Walls */}
      <instancedMesh ref={wallMesh} args={[undefined, undefined, walls.length]}>
        <boxGeometry args={[1, 1, 1]} />
        <meshStandardMaterial roughness={0.9} />
      </instancedMesh>

      {/* Exterior Environment */}
      <Cityscape />

      {/* Internal lighting */}
      <ambientLight intensity={0.5} />
      <directionalLight position={[10, 10, 5]} intensity={1.5} color="#fff8f0" />
    </SceneFrame>
  );
}

function Cityscape() {
  const city = useGLTF("/glb/city_pack.glb");
  const block = useGLTF("/glb/modern_city_block.glb");

  return (
    <group position={[0, -2, -30]} scale={5}>
      <primitive object={city.scene.clone()} position={[-10, 0, 0]} />
      <primitive object={block.scene.clone()} position={[10, 0, 5]} />
      <primitive object={city.scene.clone()} position={[0, 0, 15]} rotation={[0, Math.PI/2, 0]} />
    </group>
  );
}

