3: import { Component, type ReactNode } from "react";
4: 
5: /**
6:  * Catches anything a WebGL subtree throws, and notices when the GPU drops it.
7:  *
8:  * A lost context, a driver fault or an out-of-memory kill inside a Three.js
9:  * scene would otherwise unmount the whole route. Every scene on this site sits
10:  * over content that already works, so the correct response to a failure is to
11:  * render the fallback and let that content stand.
12:  *
13:  * The `webglcontextlost` listener matters more than it looks. That event does
14:  * not throw, so an error boundary alone never sees it — the canvas simply stops
15:  * updating and the visitor is left staring at a frozen last frame or a black
16:  * rectangle. It is also not a rare event now that three heavy scenes can exist
17:  * on one journey: browsers cap how many live contexts a page may hold, and a
18:  * warm phone will drop one to save itself.
19:  *
20:  * Context loss is recoverable, so it is tracked separately from a thrown error:
21:  * if the browser restores the context we clear the fallback and let the scene
22:  * remount. A thrown error is treated as terminal, because whatever produced it
23:  * will almost certainly produce it again.
24:  */
25: export class WebGLBoundary extends Component<
26:   { children: ReactNode; fallback?: ReactNode },
27:   { failed: boolean; contextLost: boolean }
28: > {
29:   state = { failed: false, contextLost: false };
30:   private root: HTMLDivElement | null = null;
31: 
32:   static getDerivedStateFromError() {
33:     return { failed: true };
34:   }
35: 
36:   componentDidCatch(error: unknown) {
37:     // Worth knowing about, never worth interrupting the visitor for.
38:     console.warn("[webgl] scene failed, falling back", error);
39:   }
