107:   /* Raw palette */
108:   --charcoal: #141414;
109:   --charcoal-2: #1a1a1a;
110:   --ivory: #f5f1e8;
111:   --cream: #ede7da;
112:   --gold: #b99c6b;
113:   /* Lightened gold for small text on a dark ground — 9.4:1 on --surface-0. */
114:   --gold-soft: #c9ae7c;
115:   /* Was #7A5A33, chosen to clear 4.5:1 against ivory. On a near-black ground
116:      that same value measures 1.9:1 — a hard WCAG failure — so it is lifted
117:      here. Bronze survives as the *secondary* metallic: a step down from
118:      gold-soft, used for map and floor-plan strokes where the primary accent
119:      would shout. 5.4:1 on --surface-0. */
120:   --bronze: #a8834d;
121:   --forest: #243b34;
122:   /* Forest at 1.5:1 on near-black is invisible. This lifted tone is what
123:      success states and the WhatsApp affordance actually use. */
124:   --forest-lift: #356b5c;
125:   --navy: #0a192f;
126:   --stone: #6b6b6b;
127:   --stone-2: #9a9a9a;
128: 
129:   /* --- Elevation ladder ---------------------------------------------------
130:      Deliberately deeper than --charcoal at the base, so charcoal itself is
131:      freed up to be a *surface* rather than the ground. That one step is what
132:      lets cards and sections separate without borders doing all the work. */
133:   --surface-0: #0d0d0d; /* page ground */
134:   --surface-1: #141414; /* cards, footer */
135:   --surface-2: #1a1a1a; /* alternating sections */
136:   --surface-3: #242424; /* elevated emphasis blocks */
137:   --hairline: rgb(245 241 232 / 10%);
138:   --hairline-strong: rgb(245 241 232 / 18%);
139: 
140:   /* Semantic */
141:   --background: var(--surface-0);
142:   --foreground: var(--ivory);
143:   --card: var(--surface-1);
144:   --card-foreground: var(--ivory);
145:   --popover: var(--surface-2);
146:   --popover-foreground: var(--ivory);
147:   --primary: var(--ivory);
148:   --primary-foreground: var(--charcoal);
149:   --secondary: var(--surface-2);
150:   --secondary-foreground: var(--ivory);
151:   --muted: var(--surface-2);
152:   --muted-foreground: var(--stone-2);
153:   --accent: var(--gold-soft);
154:   --accent-foreground: var(--charcoal);
155:   --destructive: #c96a6a;
156:   --border: var(--hairline);
157:   --input: var(--hairline-strong);
158:   --ring: var(--gold-soft);
159:   --radius: 0.25rem;
160: }
161: 
162: @layer base {
163:   * {
164:     @apply border-border outline-ring/50;
165:   }
166:   html {
167:     @apply font-sans;
168:     /* Lenis needs this off; we re-enable natively when motion is reduced. */
169:     scroll-behavior: auto;
170:   }
171:   body {
172:     @apply bg-background text-foreground antialiased;
173:     text-rendering: optimizeLegibility;
174:   }
175:   h1,
176:   h2,
177:   h3,
178:   h4,
179:   h5 {
180:     @apply font-display;
181:     font-optical-sizing: auto;
182:     letter-spacing: -0.015em;
183:   }
184:   :lang(gu) {
185:     font-family: var(--font-gujarati), var(--font-manrope), sans-serif;
186:   }
187:   ::selection {
188:     background: var(--gold);
189:     color: var(--charcoal);
190:   }
191:   /* The `outline-ring/50` on `*` was tuned against ivory. At 50% opacity on a
192:      near-black ground it is close to invisible, and an invisible focus ring is
193:      an accessibility regression rather than a styling preference. */
194:   :focus-visible {
195:     outline: 2px solid var(--gold-soft);
196:     outline-offset: 2px;
197:   }
198: }
199: 
200: /* ------------------------------------------------------------------------- *
201:  * Stacking order. Written down because three fixed layers plus a full-screen *
202:  * gate is exactly the situation where z-index becomes folklore.              *
203:  *                                                                            *
204:  *   10  in-page sticky UI                                                    *
205:  *   50  SiteHeader, StickyMobileActionBar                                    *
206:  *   60  gallery lightbox                                                     *
207:  *   80  pre-paint cover (html[data-onboarding="pending"]::before)            *
208:  *   90  OnboardingGate                                                       *
209:  *  110  skip link on focus — above everything, always reachable              *
210:  * ------------------------------------------------------------------------- */
211: 
212: @layer components {
213:   /* Small uppercase eyebrows / nav labels — generous tracking reads expensive. */
214:   .eyebrow {
215:     @apply font-sans text-caption uppercase;
216:     letter-spacing: 0.18em;
217:   }
218: 
219:   /* Page gutter + max width. Whitespace is the luxury: see CLAUDE.md §6. */
220:   .container-page {
221:     @apply mx-auto w-full px-6 md:px-10 lg:px-16;
222:     max-width: var(--container-page);
223:   }
224: 
225:   /* Standard vertical section rhythm — deliberately 2–3× template defaults. */
226:   .section {
227:     @apply py-24 md:py-32;
228:   }
229: 
230:   /* Editorial measure: 50–75 characters. */
231:   .measure {
232:     max-width: 68ch;
233:   }
234: 
235:   /* Hairline rule in the brand's low-contrast register. */
236:   .rule {
237:     @apply border-t border-border;
238:   }
239: 
240:   /* Availability stack cells. A tall tower emits hundreds of these, so the
241:      status styling lives here on a data attribute rather than as repeated
242:      utility strings — it keeps tens of kilobytes out of the HTML. */
243:   .unit-cell {
244:     display: block;
245:     height: 0.9rem;
246:     width: 1.9rem;
247:     border-radius: 2px;
248:     background: var(--border);
249:   }
250:   .unit-cell[data-status="available"] {
251:     background: var(--forest-lift);
252:   }
253:   .unit-cell[data-status="blocked"] {
254:     background: var(--gold);
255:     opacity: 0.55;
256:   }
257: 
258:   /* MapLibre markers are plain DOM, so they take the brand palette rather
259:      than the library's defaults. */
260:   .map-marker {
261:     width: 0.85rem;
262:     height: 0.85rem;
263:     border-radius: 9999px;
264:     background: var(--stone-2);
265:     /* The ring is the page ground, not ivory: on a dark map the marker should
266:        read as punched out of the surface rather than ringed in white. */
267:     border: 2px solid var(--surface-0);
268:     box-shadow: 0 0 0 1px rgb(245 241 232 / 12%);
269:     cursor: pointer;
270:   }
271:   .map-marker[data-state="has-projects"] {
272:     background: var(--gold);
273:   }
274:   .map-marker[data-state="active"] {
275:     background: var(--bronze);
276:     width: 1.15rem;
277:     height: 1.15rem;
278:   }
279: }
