281: /* The WebGL hero fades in only once it has decided the device can afford it,
282:    so it never competes with the LCP paint. */
283: @keyframes fade-in-canvas {
284:   from {
285:     opacity: 0;
286:   }
287:   to {
288:     opacity: 1;
289:   }
290: }
291: 
292: /* Hero entrance. Staggered by delay on each line rather than by JavaScript,
293:    so the headline is styled and animated straight out of the server HTML. */
294: @keyframes rise {
295:   from {
296:     opacity: 0;
297:     transform: translateY(24px);
298:   }
299:   to {
300:     opacity: 1;
301:     transform: none;
302:   }
303: }
304: 
305: @keyframes nudge {
306:   0%,
307:   100% {
308:     transform: translateY(0);
309:     opacity: 0.5;
310:   }
311:   50% {
312:     transform: translateY(6px);
313:     opacity: 1;
314:   }
315: }
316: 
317: /* Users who ask for less motion get none of the choreography. */
318: @media (prefers-reduced-motion: reduce) {
319:   html {
320:     scroll-behavior: auto !important;
321:   }
322:   *,
323:   *::before,
324:   *::after {
325:     animation-duration: 0.01ms !important;
326:     animation-iteration-count: 1 !important;
327:     transition-duration: 0.01ms !important;
328:     scroll-behavior: auto !important;
